import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第二十六卦 大畜 山天大畜 艮上乾下","description":"周易 - 第二十六卦 大畜 山天大畜 艮上乾下","frontmatter":{"title":"第二十六卦 大畜 山天大畜 艮上乾下","description":"周易 - 第二十六卦 大畜 山天大畜 艮上乾下"},"headers":[],"relativePath":"zh/classics/zhouyi/027.md","filePath":"zh/classics/zhouyi/027.md"}'),l={name:"zh/classics/zhouyi/027.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="大畜" tabindex="-1">大畜 <a class="header-anchor" href="#大畜" aria-label="Permalink to “大畜”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>利贞，不家食吉，利涉大川。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>大畜，刚健笃实辉光，日新其德，刚上而尚贤。能止健，大正也。不家食吉，养贤也。利涉大川，应乎天也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>天在山中，大畜；君子以多识前言往行，以畜其德。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>有厉利已。象曰：有 厉利已，不犯灾也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>舆说辐。象曰：舆说辐，中无尤也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>良马逐，利艰贞。曰闲舆卫，利有攸往。象曰：利有攸往，上合志也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>童豕之牿，元吉。象曰：六四元吉，有喜也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>豶豕之牙，吉。象曰：六五之吉，有庆也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>何天之衢，亨。象曰：何天之衢，道大行也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
